package local.proskurnin.remote;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import java.net.*;
public class RemoteService extends Service {
 static volatile RemoteService instance;RemoteAuth auth;volatile RemoteHttp server,secureServer;volatile String status="Запуск…";final Handler h=new Handler();boolean awake=true;volatile boolean bridgeReady;boolean checkingBridge;ConnectivityManager.NetworkCallback networks;
 final BroadcastReceiver power=new BroadcastReceiver(){public void onReceive(Context c,Intent i){awake=Intent.ACTION_SCREEN_ON.equals(i.getAction());refresh();}};
 final Runnable monitor=new Runnable(){public void run(){refresh();if(!checkingBridge){checkingBridge=true;new Thread(()->{boolean ready=BridgeClient.send("PING");h.post(()->{bridgeReady=ready;checkingBridge=false;});},"remote-bridge-check").start();}h.postDelayed(this,5000);}};
 public void onCreate(){super.onCreate();instance=this;auth=new RemoteAuth(this);awake=((PowerManager)getSystemService(POWER_SERVICE)).isInteractive();NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("remote_server","Пульт с телефона",NotificationManager.IMPORTANCE_MIN));Intent settings=new Intent(this,RemoteActivity.class);Notification n=new Notification.Builder(this,"remote_server").setSmallIcon(android.R.drawable.ic_menu_send).setContentTitle("Пульт с телефона включён").setContentText("Управление только в домашней сети").setContentIntent(PendingIntent.getActivity(this,0,settings,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setOngoing(true).build();startForeground(42,n);
  IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_SCREEN_ON);f.addAction(Intent.ACTION_SCREEN_OFF);registerReceiver(power,f);networks=new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){h.post(()->refresh());}public void onLost(Network n){h.post(()->refresh());}public void onLinkPropertiesChanged(Network n,LinkProperties p){h.post(()->refresh());}};
  ((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).registerNetworkCallback(new NetworkRequest.Builder().addTransportType(NetworkCapabilities.TRANSPORT_ETHERNET).addTransportType(NetworkCapabilities.TRANSPORT_WIFI).build(),networks);h.post(monitor);
 }
 void closeServer(){RemoteHttp old=server;server=null;if(old!=null)old.close();RemoteHttp secure=secureServer;secureServer=null;if(secure!=null)secure.close();if(auth!=null)auth.closePairing();TextInputService.reset();}
 void refresh(){if(!awake){closeServer();status="Сон · сервер остановлен";return;}try{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Inet4Address chosen=null;int bits=0;for(int type:new int[]{NetworkCapabilities.TRANSPORT_ETHERNET,NetworkCapabilities.TRANSPORT_WIFI}){for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);LinkProperties link=cm.getLinkProperties(n);if(cap==null||link==null||cap.hasTransport(NetworkCapabilities.TRANSPORT_VPN)||!cap.hasTransport(type))continue;String name=link.getInterfaceName();if(name==null)continue;for(LinkAddress address:link.getLinkAddresses())if(address.getAddress() instanceof Inet4Address&&RemoteHttp.privateV4(address.getAddress().getAddress())&&address.getPrefixLength()>=16&&address.getPrefixLength()<=30){chosen=(Inet4Address)address.getAddress();bits=address.getPrefixLength();break;}if(chosen!=null)break;}if(chosen!=null)break;}
  if(chosen==null){closeServer();status="Ожидаю домашнюю сеть LAN / Wi-Fi";return;}if(server!=null&&server.address.equals(chosen)&&server.prefix==bits)return;closeServer();server=new RemoteHttp(this,chosen,bits,false);try{secureServer=new RemoteHttp(this,chosen,bits,true);status="HTTPS · только домашняя сеть";}catch(Exception tls){status="HTTP · сертификат HTTPS не настроен";}
 }catch(Exception e){closeServer();status="Не удалось открыть локальный сервер";}}
 public int onStartCommand(Intent i,int flags,int id){if(!getSharedPreferences("remote",0).getBoolean("enabled",false)){stopSelf();return START_NOT_STICKY;}return START_STICKY;}
 public IBinder onBind(Intent i){return null;}
 public void onDestroy(){h.removeCallbacksAndMessages(null);closeServer();try{unregisterReceiver(power);}catch(Exception ignored){}try{((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).unregisterNetworkCallback(networks);}catch(Exception ignored){}instance=null;stopForeground(true);super.onDestroy();}
 String url(){RemoteHttp s=secureServer!=null?secureServer:server;return s==null?"":s.originBase+"/";}
}
